"""Manoeuvre-based mock-flight scenario builder -- BL-B104 Stage 7
(`plans/bl-b104-ground-contacts-on-ground/plan.md`'s "Manoeuvre-based
scenario mock flights"). Turns a short list of flight legs plus placed
ground units into a frame list in the exact shape
`tests.support.mock_aircraft_layer.MockAircraftLayerServer` already
consumes (`list[{"telemetry", "world_objects", "petrovich_indication",
"line_of_sight"}]`), generated by code rather than hand-written JSON --
`tests/fixtures/mock_flight_canonical.json` is one flight, authored once;
a manoeuvre scenario is legs integrated into a trajectory, which code is
for.

**`Level`/`Descend`/`Turn` are implemented**, not the plan's full
`Level`/`Climb`/`Descend`/`Turn`/`RunIn`/`Hover` sketch -- these are the
only kinds Stage 7's own four scenarios actually need (a closing or
shallow-approach run is `Level` or `Descend` at a constant heading; the
pitched-recovery cockpit-mask case is a `Descend` to a lower altitude and
steeper nose-down pitch, same heading throughout; `Turn` was added by the
Stage 7 amendment, review.md Finding 2, for a real heading-change
manoeuvre). Per the plan's own "how a later feature adds a scenario" step,
a scenario needing `Climb`/`RunIn`/`Hover` adds that leg kind here when it
is actually needed, rather than this module carrying untested kinds up
front.

Integration is dead-reckoning only (heading/pitch/altitude applied once
per poll tick, straight-line in x/z) -- no aerodynamics, no world-model
terrain under the flight path (ownship altitude is a leg parameter, not
derived from a grid, matching `mock_world_model.build_mock_world_model`'s
own flat-plane precedent). A leg's own kinematics (e.g. an instant heading
snap between legs) are not a flight-model claim.

Fully deterministic by construction: every per-look noise draw downstream
(`perception.estimation`/`perception.naked_eye_source`) is a hash of the
observation id/object id, not a stateful RNG, so a fixed `ownship_start`/
leg list/unit list reproduces bit-identical frames and bit-identical
believed positions on every run -- no explicit seed needed here."""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any

from coordinates import dcs_to_wgs84

Frame = dict[str, Any]


@dataclass(frozen=True, slots=True)
class OwnshipStart:
    """Ownship's state at `t_sim=0`, before any leg is integrated."""

    x: float
    z: float
    heading_deg: float
    altitude_msl_m: float
    altitude_agl_m: float


@dataclass(frozen=True, slots=True)
class Level:
    """Straight, level flight: heading/altitude/speed all held constant
    for the leg's own duration."""

    duration_s: float
    speed_mps: float
    heading_deg: float
    altitude_msl_m: float
    altitude_agl_m: float
    pitch_deg: float = 0.0


@dataclass(frozen=True, slots=True)
class Descend:
    """Straight flight at a fixed heading, altitude ramping linearly from
    whatever the ownship holds when this leg begins to
    `end_altitude_msl_m`/`end_altitude_agl_m` over `duration_s`."""

    duration_s: float
    speed_mps: float
    heading_deg: float
    end_altitude_msl_m: float
    end_altitude_agl_m: float
    pitch_deg: float


@dataclass(frozen=True, slots=True)
class Turn:
    """Heading ramps linearly from whatever the ownship holds when this
    leg begins to `end_heading_deg` over `duration_s`, at constant
    speed/altitude. `bank_deg` is a stated telemetry value for the turn's
    duration (dead-reckoning only, per the module docstring -- not derived
    from a standard-rate-turn formula), mirroring how `pitch_deg` is
    already a leg parameter rather than a derived quantity."""

    duration_s: float
    speed_mps: float
    end_heading_deg: float
    altitude_msl_m: float
    altitude_agl_m: float
    bank_deg: float
    pitch_deg: float = 0.0


#: The builder's own leg vocabulary (module docstring) -- extend with a
#: new dataclass plus a branch in `build_scenario_frames` when a scenario
#: genuinely needs one, not speculatively.
FlightLeg = Level | Descend | Turn


@dataclass(frozen=True, slots=True)
class PlacedUnit:
    """One stationary ground unit. `object_id`/`unit_name` are the join
    keys `perception.association.WorldObjectCandidate.from_dict`/the LOS
    verdict dict both key off (`aircraft-layer/src/schema/world_objects.py`,
    `aircraft-layer/src/schema/line_of_sight.py`). `category`/`subcategory`
    are `LoGetWorldObjects`' `Type.level1`/`Type.level2` (BL-B104 Stage 1)
    -- every placed unit here is a ground vehicle, `category=2`
    (`perception.domain._WS_TYPE_GROUND`), so the fused range/altitude
    model under test actually runs. No velocity field -- no scenario here
    needs a moving unit; add one later if one does."""

    object_id: int
    unit_name: str
    object_type: str
    x: float
    z: float
    ground_alt_m: float
    category: int = 2
    subcategory: int | None = None


def build_scenario_frames(
    ownship_start: OwnshipStart,
    legs: list[FlightLeg],
    placed_units: list[PlacedUnit],
    *,
    theatre: str,
    poll_interval_s: float = 5.0,
    start_wall_clock_s: float = 1000.0,
) -> list[Frame]:
    """Integrate `legs` from `ownship_start` into a frame list, one frame
    at `t_sim=0` (the start state) plus one frame per poll tick of every
    leg thereafter. Each placed unit's fixed DCS x/z is converted to
    lat/lon once (`coordinates.dcs_to_wgs84`, the same real-geometry
    convention `mock_flight_canonical.json`'s own derivation used), since
    every unit here is stationary. `petrovich_indication` is left absent
    on every frame (`None` once served) -- these scenarios exercise the
    naked-eye/9K113 sight path, not the Hybrid HelperAI channel, and
    leaving it unset keeps that channel contributing nothing. Every
    placed unit gets a `building_clear=True, terrain_clear=True` LOS
    verdict on every frame -- the flat, clear-by-construction world model
    `mock_world_model.build_mock_world_model`/`build_flat_world_model`
    already provides for the terrain-LOS gate, matched here for the
    Hook-wire LOS gate so neither gate is the thing under test."""
    unit_lat_lon = {
        unit.object_id: dcs_to_wgs84(theatre, unit.x, unit.z) for unit in placed_units
    }

    t_sim = 0.0
    x = ownship_start.x
    z = ownship_start.z
    heading_deg = ownship_start.heading_deg
    pitch_deg = 0.0
    bank_deg = 0.0
    altitude_msl_m = ownship_start.altitude_msl_m
    altitude_agl_m = ownship_start.altitude_agl_m
    speed_mps = 0.0

    frames: list[Frame] = []

    def emit() -> None:
        frames.append(
            _build_frame(
                t_sim=t_sim,
                wall_clock_s=start_wall_clock_s + t_sim,
                x=x,
                z=z,
                heading_deg=heading_deg,
                pitch_deg=pitch_deg,
                bank_deg=bank_deg,
                speed_mps=speed_mps,
                altitude_msl_m=altitude_msl_m,
                altitude_agl_m=altitude_agl_m,
                placed_units=placed_units,
                unit_lat_lon=unit_lat_lon,
            )
        )

    emit()

    for leg in legs:
        n_steps = max(1, round(leg.duration_s / poll_interval_s))
        pitch_deg = leg.pitch_deg
        speed_mps = leg.speed_mps
        start_altitude_msl_m = altitude_msl_m
        start_altitude_agl_m = altitude_agl_m
        if isinstance(leg, (Level, Turn)):
            end_altitude_msl_m = leg.altitude_msl_m
            end_altitude_agl_m = leg.altitude_agl_m
        else:
            end_altitude_msl_m = leg.end_altitude_msl_m
            end_altitude_agl_m = leg.end_altitude_agl_m

        if isinstance(leg, Turn):
            # Heading is interpolated per step (entry heading -> leg's own
            # end_heading_deg), unlike Level/Descend, whose heading/dx/dz
            # are fixed once for the whole leg -- a Turn is the one leg
            # kind whose own direction of travel changes within itself.
            start_heading_deg = heading_deg
            end_heading_deg = leg.end_heading_deg
            bank_deg = leg.bank_deg
            for step in range(1, n_steps + 1):
                fraction = step / n_steps
                heading_deg = start_heading_deg + fraction * (
                    end_heading_deg - start_heading_deg
                )
                heading_rad = math.radians(heading_deg)
                x += speed_mps * poll_interval_s * math.cos(heading_rad)
                z += speed_mps * poll_interval_s * math.sin(heading_rad)
                t_sim += poll_interval_s
                altitude_msl_m = start_altitude_msl_m + fraction * (
                    end_altitude_msl_m - start_altitude_msl_m
                )
                altitude_agl_m = start_altitude_agl_m + fraction * (
                    end_altitude_agl_m - start_altitude_agl_m
                )
                emit()
            bank_deg = 0.0
        else:
            heading_deg = leg.heading_deg
            heading_rad = math.radians(heading_deg)
            dx = speed_mps * poll_interval_s * math.cos(heading_rad)
            dz = speed_mps * poll_interval_s * math.sin(heading_rad)
            for step in range(1, n_steps + 1):
                x += dx
                z += dz
                t_sim += poll_interval_s
                fraction = step / n_steps
                altitude_msl_m = start_altitude_msl_m + fraction * (
                    end_altitude_msl_m - start_altitude_msl_m
                )
                altitude_agl_m = start_altitude_agl_m + fraction * (
                    end_altitude_agl_m - start_altitude_agl_m
                )
                emit()

    return frames


def _build_frame(
    *,
    t_sim: float,
    wall_clock_s: float,
    x: float,
    z: float,
    heading_deg: float,
    pitch_deg: float,
    bank_deg: float,
    speed_mps: float,
    altitude_msl_m: float,
    altitude_agl_m: float,
    placed_units: list[PlacedUnit],
    unit_lat_lon: dict[int, tuple[float, float]],
) -> Frame:
    telemetry = {
        "dcs_model_time_s": t_sim,
        "received_wall_clock_s": wall_clock_s,
        "position_x_m": x,
        "position_y_m": altitude_msl_m,
        "position_z_m": z,
        "pitch_rad": math.radians(pitch_deg),
        "bank_rad": math.radians(bank_deg),
        "yaw_rad": 0.0,
        "heading_true_rad": math.radians(heading_deg % 360.0),
        "ias_mps": speed_mps,
        "tas_mps": speed_mps,
        "altitude_msl_m": altitude_msl_m,
        "altitude_agl_m": altitude_agl_m,
        "altitude_radar_m": altitude_agl_m,
    }
    objects = []
    verdicts = {}
    for unit in placed_units:
        lat_deg, lon_deg = unit_lat_lon[unit.object_id]
        objects.append(
            {
                "object_id": unit.object_id,
                "object_type": unit.object_type,
                "coalition": 2.0,
                "lat_deg": lat_deg,
                "lon_deg": lon_deg,
                "altitude_m": unit.ground_alt_m,
                "heading_true_rad": 0.0,
                "is_ownship": False,
                "unit_name": unit.unit_name,
                "category": unit.category,
                "subcategory": unit.subcategory,
            }
        )
        verdicts[unit.unit_name] = {"building_clear": True, "terrain_clear": True}
    world_objects = {
        "dcs_model_time_s": t_sim,
        "received_wall_clock_s": wall_clock_s,
        "objects": objects,
    }
    line_of_sight = {
        "dcs_model_time_s": t_sim,
        "received_wall_clock_s": wall_clock_s,
        "hour_used": None,
        "fov_half_deg_used": None,
        "verdicts": verdicts,
    }
    return {
        "telemetry": telemetry,
        "world_objects": world_objects,
        "petrovich_indication": None,
        "line_of_sight": line_of_sight,
    }
